'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STORE='cyber-studio-v1';
let storageAvailable=true,state={done:[],answers:{},notes:{},saved:[],projects:{},profile:null,stage:0,track:'all',pipelineLab:false};
try{const raw=localStorage.getItem(STORE);if(raw){const saved=JSON.parse(raw);if(saved&&typeof saved==='object')state={...state,...saved};}if(!Array.isArray(state.done))state.done=[];if(!Array.isArray(state.saved))state.saved=[];if(!state.answers||typeof state.answers!=='object'||Array.isArray(state.answers))state.answers={};if(!state.notes||typeof state.notes!=='object'||Array.isArray(state.notes))state.notes={};if(!state.projects||typeof state.projects!=='object'||Array.isArray(state.projects))state.projects={};if(![0,1,2].includes(state.stage))state.stage=0;if(!['all','cyber','data'].includes(state.track))state.track='all';}catch(e){storageAvailable=false;}
let resourceFilter='All',resourceQuery='',onlySaved=false,toastTimer;
const persist=()=>{try{localStorage.setItem(STORE,JSON.stringify(state));}catch(e){storageAvailable=false;toast('Browser storage unavailable. Changes last for this visit.');}};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800);}
const icons={shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6Z"/><path d="m8 12 3 3 5-6"/>',network:'<rect x="8" y="2" width="8" height="6" rx="1"/><rect x="2" y="16" width="7" height="5" rx="1"/><rect x="15" y="16" width="7" height="5" rx="1"/><path d="M12 8v5M5 16v-3h14v3"/>',terminal:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m7 9 3 3-3 3m6 0h4"/>',key:'<circle cx="8" cy="9" r="5"/><path d="m12 13 8 8m-4-4 3-3m-6 0 3-3"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',cloud:'<path d="M7 18h11a4 4 0 0 0 0-8 6 6 0 0 0-11-2 5 5 0 0 0 0 10Z"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6h14M5 18h14"/>',layers:'<path d="m12 3 10 6-10 6L2 9Zm-10 10 10 6 10-6M2 17l10 6 10-6"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6Z"/>',book:'<path d="M3 3h7l2 2 2-2h7v17h-7l-2 2-2-2H3Z"/><path d="M12 5v17M6 8h3M6 12h3m6-4h3m-3 4h3"/>',lab:'<path d="M9 3h6M10 3v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M7 15h10"/>',bookmark:'<path d="M5 3h14v19l-7-5-7 5Z"/>',home:'<path d="m3 10 9-7 9 7v11h-7v-7h-4v7H3Z"/>',play:'<path d="m8 4 13 8-13 8Z"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.shield}</svg>`;
const brand=()=>`<a class="brand" href="#home" aria-label="NxGenVarsity home"><span class="brand-mark">${icon('shield')}</span><span>NxGenVarsity<span style="color:var(--gold)">.</span></span></a>`;
// Stable card colors stay with a topic when lists are searched or filtered.
function cardTone(key){const named={soc:'mint',appsec:'violet',pentest:'peach',dfir:'rose',grc:'gold',shield:'mint',activity:'mint',lab:'mint',network:'sky',cloud:'sky',globe:'sky',code:'violet',terminal:'violet',key:'gold',layers:'gold',search:'peach',compass:'peach',spark:'rose',Course:'mint',Lab:'sky',Reference:'violet',Framework:'gold',Tool:'peach',Career:'mint',Certification:'rose','Threat intel':'sky',credentials:'rose',frameworks:'gold',institutions:'sky',law:'peach',research:'violet'};if(named[key])return named[key];return ['mint','sky','violet','peach','gold','rose'][Array.from(String(key)).reduce((n,c)=>n+c.charCodeAt(0),0)%6];}
const stageNames=['Foundations','Build & defend','Specialize'];
const lessonTotal=modules.reduce((n,m)=>n+m.lessons.length,0);
const moduleDone=m=>m.lessons.every((l,i)=>state.done.includes(`${m.id}:${i}`));
const moduleCount=()=>modules.filter(moduleDone).length;
const totalDone=()=>modules.reduce((n,m)=>n+m.lessons.filter((l,i)=>state.done.includes(`${m.id}:${i}`)).length,0);
function nextLesson(){for(const m of guidedModules())for(let i=0;i<m.lessons.length;i++)if(!state.done.includes(`${m.id}:${i}`))return `#lesson/${m.id}/${i}`;return '#progress';}
function courseModules(course){return modules.filter(m=>course==='data'?m.course==='data':m.course!=='data');}
function courseLessonCount(course){return courseModules(course).reduce((n,m)=>n+m.lessons.length,0);}
function courseDoneCount(course){return courseModules(course).reduce((n,m)=>n+m.lessons.filter((l,i)=>state.done.includes(`${m.id}:${i}`)).length,0);}
function courseProgressPercent(course){const total=courseLessonCount(course);return total?Math.round(courseDoneCount(course)/total*100):0;}
function courseCard(course){
 const isData=course==='data';
 const title=isData?'Data Engineering & MLOps':'Cybersecurity';
 const eyebrow=isData?'PRODUCTION-READY DATA':'DEFEND. INVESTIGATE. BUILD.';
 const first=courseModules(course)[0];
 const done=courseDoneCount(course),total=courseLessonCount(course),percent=courseProgressPercent(course);
 const next=courseModules(course).map(m=>m.lessons.map((l,i)=>({m,l,i}))).flat().find(x=>!state.done.includes(`${x.m.id}:${x.i}`));
 return `<article class="course-dashboard-card ${isData?'course-data':'course-cyber'}">
   <div class="course-card-top"><span class="eyebrow">${eyebrow}</span><span class="course-card-icon">${icon(isData?'layers':'shield')}</span></div>
   <h2>${title}</h2>
   <p>${isData?'From reliable data systems to deployed, monitored ML workflows.':'From security foundations to defensive investigation and responsible practice.'}</p>
   <div class="course-progress-row"><span>${done} / ${total} lessons</span><strong>${percent}%</strong></div>
   <div class="course-progress" aria-label="${percent}% complete"><span style="width:${percent}%"></span></div>
   <a class="btn ${isData?'course-data-btn':'course-cyber-btn'}" href="${next?`#lesson/${next.m.id}/${next.i}`:'#progress'}">${done?'Continue course':'Start course'} <span>→</span></a>
 </article>`;
}
function shell(content,section='home'){
 const name=state.profile?.name||'Guest learner';
 const nav=[['home','compass','Overview'],['curriculum','book','Curriculum'],['labs','lab','Practice lab'],['careers','network','Career compass'],['library','book','Resource library'],['videos','play','Watch & learn'],['reference','layers','Knowledge atlas'],['checks','shield','Knowledge checks'],['progress','bookmark','My progress']];
 const trackLabel='NXGENVARSITY UNIFIED JOURNEY';
 state.track='all';
 return `<aside class="sidebar" aria-label="Sidebar"><button class="nav-close" aria-label="Close navigation">×</button>${brand()}<a class="sidebar-logo" href="#home" aria-label="NxGenVarsity Unified Platform home"><img src="assets/nxgenvarsity-logo.png" alt="NxGenVarsity" width="3615" height="624"></a><div class="brand-sub">NXGENVARSITY UNIFIED PLATFORM</div><div class="nav-label">${trackLabel}</div><nav aria-label="Main navigation">${nav.map(([id,ic,label])=>`<a class="navlink ${section===id?'active':''}" href="#${id}" ${section===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='careers'?`<small class="soon">${roles.length} paths</small>`:''}</a>`).join('')}</nav><div class="side-progress"><div class="eyebrow">YOUR OVERALL PROGRESS</div><div class="side-progress-row"><strong>${totalDone()}</strong><span>of ${lessonTotal} lessons</span></div><div class="course-progress"><span style="width:${lessonTotal?Math.round(totalDone()/lessonTotal*100):0}%"></span></div><a href="#progress">View learning journal →</a></div><div class="side-footer">Made for curious engineering minds.<br>Learn deeply. Build with purpose.</div></aside><nav class="mobile-bottom-nav" aria-label="Quick navigation"><a class="${section==='home'?'active':''}" href="#home">${icon('home')}<span>Home</span></a><a class="${section==='curriculum'?'active':''}" href="#curriculum">${icon('book')}<span>Courses</span></a><a class="${section==='labs'?'active':''}" href="#labs">${icon('lab')}<span>Practice</span></a><a class="${section==='library'?'active':''}" href="#library">${icon('bookmark')}<span>Resources</span></a><a class="${section==='progress'?'active':''}" href="#progress">${icon('compass')}<span>Progress</span></a></nav><div class="main-wrap"><header class="topbar"><div class="top-tag"><button class="mobile-toggle" aria-label="Toggle navigation" aria-expanded="false">☰</button><span>Learn with purpose. Build with confidence.</span></div><div class="top-right"><span class="eyebrow">YOUR FUTURE STARTS HERE</span><a href="#login" class="profile" aria-label="Open sign-in page"><span class="avatar">${esc(name[0])}</span>${esc(name)} <span class="muted">⌄</span></a></div></header><main id="main" tabindex="-1" class="page" style="outline:none">${content}<footer class="site-footer"><span>NxGenVarsity Unified Platform</span><span>${storageAvailable?'Progress stays in this browser':'Progress is temporary for this visit'} · <a href="#login">Sign in</a> · <a href="#coverage">Coverage map</a> · <a href="#sources">Sources & credits</a></span></footer></main></div>`;
}
function moduleCard(m){let n=m.lessons.filter((l,i)=>state.done.includes(`${m.id}:${i}`)).length;let i=m.lessons.findIndex((l,j)=>!state.done.includes(`${m.id}:${j}`));if(i<0)i=0;
 return `<a href="#lesson/${m.id}/${i}" class="module" data-tone="${cardTone(m.icon)}"><div class="module-top"><span class="eyebrow">MODULE ${String(guidedModuleIds.indexOf(m.id)+1).padStart(2,'0')}</span><span class="module-icon">${icon(m.icon)}</span></div><h3>${m.title}</h3><p>${m.subtitle}</p><div class="module-foot"><span>${n===m.lessons.length?'✓ Completed':`${m.lessons.length} lessons · ${m.time}`}</span><b aria-hidden="true">↗</b></div><div class="module-progress" aria-label="${n} of 3 lessons completed"><span style="width:${n/m.lessons.length*100}%"></span></div></a>`;}
function home(){return shell(`<div class="greeting"><div><h2>${state.profile?.name?'Welcome back, '+esc(state.profile.name.split(' ')[0])+'.':'A good day to start something meaningful.'}</h2><p>Your two-course learning workspace is ready.</p></div><span class="date-pill">${lessonTotal} total lessons · ${modules.length} modules</span></div><section class="unified-hero" aria-label="NxGenVarsity learning overview"><div class="unified-hero-copy"><div class="eyebrow">NXGENVARSITY LEARNING WORKSPACE</div><h1>Build skills that work<br><em>in the real world.</em></h1><p>Move between cybersecurity and data & MLOps with one account, one dashboard, and a connected learning record.</p><div class="hero-actions"><a class="btn gold" href="${nextLesson()}">${totalDone()?'Continue learning':'Start learning'} <span>→</span></a><a class="text-link" href="#curriculum">Explore both courses <span>→</span></a></div></div><div class="unified-hero-stats"><div><strong>${moduleCount()}</strong><span>Modules completed</span></div><div><strong>${Object.values(state.answers).filter(v=>v===true).length}</strong><span>Checks passed</span></div><div><strong>${projects.reduce((n,p)=>n+Object.values(state.projects[p.id]||{}).filter(Boolean).length,0)}</strong><span>Project tasks</span></div></div></section><div class="course-dashboard-grid">${courseCard('cyber')}${courseCard('data')}</div><section aria-labelledby="path-heading"><div class="section-top"><div><h2 id="path-heading">Continue your learning journey</h2><p>Pick up where you stopped or explore a new stage.</p></div><a class="text-link" href="#curriculum">View all stages ↗</a></div>${startingPoint()}${flowStrip()}<ol class="curriculum-flow home-flow">${learningPhases.slice(0,6).map(p=>phaseCard(p)).join('')}</ol></section><div class="lower-grid"><section class="mission"><div class="eyebrow">THIS WEEK’S SMALL MISSION</div><h3>Follow the evidence.</h3><p>A burst of failed sign-ins. One unexpected success. Can you tell a password mistake from a signal worth investigating?</p><a class="text-link" href="#labs/triage">Try the sign-in challenge <span>↗</span></a></section><section class="field-note"><div class="eyebrow">FROM LEARNING TO DOING</div><h3>You don’t need to know it all.</h3><p>Start with one role, one small project, and a clear explanation of what you learned.</p><a class="text-link" href="#careers">Explore the career compass <span>↗</span></a></section></div>`);}
function heading(label,title,description){return `<div class="page-heading"><div class="eyebrow">${label}</div><h1>${title}</h1><p>${description}</p></div>`;}
function lesson(id,index){let m=modules.find(x=>x.id===id);let i=Number(index);if(!m||!Number.isInteger(i)||!m.lessons[i])return missing();let l=m.lessons[i],key=`${id}:${i}`,done=state.done.includes(key),passed=state.answers[key]===true;
return shell(`<a class="back" href="#curriculum/${phaseForModule(id).id}">← Back to this curriculum stage</a><div class="lesson-layout"><aside class="lesson-list" aria-label="Module lessons"><div class="eyebrow">${m.title}</div>${m.lessons.map((v,j)=>`<a class="lesson-link ${j===i?'active':''}" href="#lesson/${id}/${j}" ${j===i?'aria-current="step"':''}><span>${state.done.includes(`${id}:${j}`)?'✓':String(j+1).padStart(2,'0')}</span><span>${v.title}</span></a>`).join('')}</aside><article class="article"><div class="eyebrow muted">${phaseForModule(m.id).title} / MODULE ${String(guidedModuleIds.indexOf(m.id)+1).padStart(2,'0')} / LESSON ${i+1} OF ${m.lessons.length}</div><h1>${l.title}</h1><div class="lesson-body"><p>${l.body.replace('<p>','</p><p>')}</div><div class="concept"><h4>The idea to take with you</h4><p>${l.principle}</p></div>${lessonWatchPanel(m)}<h2>Put it into practice</h2><p>${l.exercise}</p><div class="lesson-practice-link"><a class="text-link" href="${phaseForModule(id).practice}">${phaseForModule(id).practiceLabel} →</a></div><h2>Go deeper with original sources</h2><div class="source-links">${m.sources.map(s=>`<a href="${R[s].url}" target="_blank" rel="noopener noreferrer">${R[s].title} ↗</a>`).join('')}</div><section class="question" aria-labelledby="question-heading"><div class="eyebrow muted">A QUICK KNOWLEDGE CHECK</div><h3 id="question-heading">${l.q}</h3><div class="answers">${l.options.map((opt,j)=>`<button class="answer ${passed&&j===l.correct?'correct':''}" data-answer="${j}" data-module="${m.id}" data-lesson="${i}"><span>${'ABC'[j]}.</span>${opt}</button>`).join('')}</div><div class="feedback" role="status">${passed?'✓ '+l.explanation:''}</div></section><h2>Your field notes</h2><label class="note-label" for="lesson-note">Explain it in your own words</label><textarea id="lesson-note" class="note-area" placeholder="What clicked? What would you like to try next?" data-note="${key}">${esc(state.notes[key]||'')}</textarea><span class="muted" style="font-size:10px">Saved automatically in this browser. Avoid personal data or credentials.</span><div class="lesson-bottom"><button class="btn ${done?'outline':''}" data-complete="${key}">${done?'✓ Lesson completed':'Mark lesson complete <span>✓</span>'}</button>${i<m.lessons.length-1?`<a class="text-link" href="#lesson/${m.id}/${i+1}">Next lesson →</a>`:guidedModuleIds.indexOf(m.id)<guidedModuleIds.length-1?`<a class="text-link" href="#lesson/${guidedModuleIds[guidedModuleIds.indexOf(m.id)+1]}/0">Next module →</a>`:'<a class="text-link" href="#progress">Review your progress →</a>'}</div></article></div>`,'curriculum');}
function library(){return shell(`${heading('THE RESOURCE LIBRARY','Good sources. Deeper understanding.','A carefully selected shelf of courses, labs, frameworks, and tools. Start with a question, then choose the resource that helps you answer it.')}${pdfDownloads()}<div class="expansion-strip"><div><b>Need a specific tool or framework?</b><span>Explore the complete knowledge atlas and source coverage.</span></div><a href="#reference/toolkit">Open the atlas ↗</a></div><div class="toolbar"><input id="resource-search" class="search" type="search" aria-label="Search resources" placeholder="Search by topic, source, or skill…" value="${esc(resourceQuery)}"><select id="resource-filter" aria-label="Filter resource type">${['All','Course','Lab','Reference','Framework','Tool','Career','Certification','Threat intel'].map(v=>`<option ${v===resourceFilter?'selected':''}>${v}</option>`).join('')}</select><button class="btn small outline" id="saved-only" aria-pressed="${onlySaved}">${onlySaved?'✓ Saved only':'Show saved'}</button></div><p id="resource-count" class="muted" style="font-size:10px;margin-bottom:15px"></p><div id="resource-grid" class="resource-grid"></div><div class="source-credit">Curated on 2 November 2026. External platforms may require their own account; availability and certification costs can change. Course materials belong to their original creators.</div>`,'library');}
function updateResources(){let result=resources.filter(r=>(resourceFilter==='All'||r.type===resourceFilter)&&(!onlySaved||state.saved.includes(r.id))&&`${r.title} ${r.type} ${r.level} ${r.desc}`.toLowerCase().includes(resourceQuery.toLowerCase()));$('#resource-count').textContent=`${result.length} resource${result.length===1?'':'s'} · Original sources, chosen for learning value`;$('#resource-grid').innerHTML=result.length?result.map(resourceCard).join(''):'<div class="empty">No resources match your search. Try a broader topic or another filter.</div>';}
function resourceCard(r){return `<article class="resource-card" data-tone="${cardTone(r.type)}"><div class="eyebrow">${r.type} · ${r.level}</div><h3>${r.title}</h3><p>${r.desc}</p><div class="resource-actions">${r.brief?`<button class="text-link" style="border:0;background:none;padding:0" data-study-brief="${r.brief}">Read study brief ↗</button>`:`<a class="text-link" target="_blank" rel="noopener noreferrer" href="${R[r.ref].url}">Explore resource ↗</a>`}<button class="bookmark ${state.saved.includes(r.id)?'saved':''}" data-save="${r.id}" aria-pressed="${state.saved.includes(r.id)}">${state.saved.includes(r.id)?'✓ Saved':'+ Save'}</button></div></article>`;}
function careers(){return shell(`${heading('THE CAREER COMPASS','Find the work that moves you.','Cybersecurity is a field of many paths. Explore the day-to-day work, the foundations to build, and one project that helps you demonstrate your skills.')}<div class="banner"><b>Your engineering background is a starting point.</b> Try a path through practical work before choosing a credential. Titles and entry requirements vary between employers.</div><div class="toolbar"><input class="search" id="career-search" type="search" aria-label="Search career paths" placeholder="Search careers, skills, or daily work…"></div><p class="muted" id="career-count">${roles.length} career orientations · Includes adjacent AI/cloud pathways</p><div class="career-grid">${roles.map(r=>`<article class="career" data-tone="${cardTone(r.id)}"><span class="module-icon">${icon(r.icon)}</span><div class="eyebrow muted">${r.tag}</div><h3>${r.title}</h3><p>${r.desc}</p><div class="tags">${r.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><a class="text-link" href="#career/${r.id}">Explore this roadmap <span>↗</span></a></article>`).join('')}</div><div class="source-credit">These are suggested study sequences, not hiring guarantees. Career exploration reference: <a href="${R.nice.url}" target="_blank" rel="noopener noreferrer">NIST NICE career pathway resources ↗</a>.</div>`,'careers');}
function career(id){let r=roles.find(x=>x.id===id);if(!r)return missing();return shell(`<a class="back" href="#careers">← All career paths</a>${heading(r.tag,r.title,r.desc)}<div class="banner"><b>A day in the role.</b> ${r.daily}</div><div class="section-top"><div><h2>A suggested route</h2><p>Move at your own pace. Demonstrate each skill before moving on.</p></div></div><div class="timeline">${r.milestones.map((x,i)=>`<div class="timeline-item"><div class="timeline-num">${String(i+1).padStart(2,'0')}</div><div><h3>${['Build your foundations','Practice with intention','Create your evidence','Prepare for the next step'][i]}</h3><p>${x}</p></div></div>`).join('')}</div><div class="field-links"><a href="#reference/toolkit" data-role-toolkit="${r.id}">Explore relevant tools →</a><a href="#reference/credentials">Compare credentials and status →</a></div><div class="section-top"><div><h2>Your core modules</h2><p>A focused selection from the learning path.</p></div></div><div class="module-grid">${r.modules.map(id=>moduleCard(modules.find(m=>m.id===id))).join('')}</div><div class="lower-grid"><div class="mission"><div class="eyebrow">ONE PROJECT TO START</div><h3>${projects.find(p=>p.id===r.project).title}</h3><p>Build something you can explain, reproduce, and improve.</p><a class="text-link" href="#project/${r.project}">Open project brief ↗</a></div><div class="field-note"><div class="eyebrow">OPTIONAL STUDY STRUCTURE</div><h3>${R[r.credential].title}</h3><p>Compare current objectives, prerequisites, and costs. This is an optional foundation, not a role qualification or job guarantee.</p><a class="text-link" target="_blank" rel="noopener noreferrer" href="${R[r.credential].url}">Review official details ↗</a></div></div>`,'careers');}
function labs(){return shell(`${heading('THE PRACTICE LAB','Make the knowledge yours.','Read a signal. Test an assumption. Write down what you learned. Start with small browser-based exercises, then build portfolio projects that demonstrate your engineering reasoning.')}<div class="field-links"><a href="#field">Ten beginner challenges →</a><a href="#field/terminal">Simulated terminal →</a><a href="#field/throttle">Throttle model →</a><a href="#labs/pipeline">Pipeline lab →</a><a href="#field/glossary">Glossary →</a></div><div class="banner"><b>A safe place to practice.</b> All exercises here run in your browser using synthetic data and workflow simulations. Explore freely without any risk or complex installation.</div><section class="hero" style="min-height:240px;grid-template-columns:1fr .72fr"><div class="hero-copy"><div class="eyebrow">CYBER TRIAGE LAB · 5 MINUTES · NO SETUP</div><h1 style="font-size:30px">One login.<br><em>More than one explanation.</em></h1><p>Investigate a synthetic sign-in log and choose an evidence-based response.</p><div class="hero-actions"><a class="btn gold" href="#labs/triage">Start the triage exercise ↗</a></div></div><div class="hero-art"><div class="log-block" style="margin:0;font-size:10px;transform:rotate(-2deg);background:#ffffff0c;border:1px solid #ffffff15">09:41:02  SIGN_IN_FAILED<br>09:41:07  SIGN_IN_FAILED<br>09:41:11  SIGN_IN_SUCCESS<br><span style="color:var(--gold)">→ What would you check next?</span></div></div></section><section class="hero" style="min-height:220px;grid-template-columns:1fr .72fr;margin-top:20px"><div class="hero-copy"><div class="eyebrow">DATA & MLOPS LAB · 5 MINUTES · INTERACTIVE</div><h2 style="font-size:28px">From dataset to deployment.<br><em>Connect the lifecycle.</em></h2><p>Arrange the stages of a production machine learning pipeline and verify your workflow logic.</p><div class="hero-actions"><a class="btn gold" href="#labs/pipeline">Start the pipeline lab ↗</a></div></div><div class="hero-art"><div class="log-block" style="margin:0;font-size:11px;transform:rotate(2deg);background:#ffffff0c;border:1px solid #ffffff15">01  Ingest data<br>02  Validate data<br>03  Engineer features<br>04  Train model<br><span style="color:var(--gold)">→ Where does evaluation fit?</span></div></div></section>${pdfDownloads(['safe-cyber-lab-starter-workbook','soc-investigation-workbook','web-security-project-playbook','data-mlops-project-workbook'])}<div class="section-top"><div><h2>Build your engineering portfolio</h2><p>${projects.length} guided projects. Clear deliverables. Evidence you can explain.</p></div></div><div class="career-grid">${projects.map(p=>`<article class="career" data-tone="${cardTone(p.icon)}"><span class="module-icon">${icon(p.icon)}</span><div class="eyebrow muted">${p.type}</div><h3>${p.title}</h3><p>${p.desc}</p><div class="tags"><span class="tag">${Object.values(state.projects[p.id]||{}).filter(Boolean).length} / ${p.deliverables.length} deliverables</span><span class="tag">Guided project</span></div><a class="text-link" href="#project/${p.id}">Open the project brief ↗</a></article>`).join('')}</div><div class="section-top"><div><h2>Ready for a larger sandbox?</h2><p>Continue with trusted, purpose-built learning platforms.</p></div></div><div class="resource-grid">${resources.filter(r=>['portswigger','linux','cylab','juice'].includes(r.id)).map(resourceCard).join('')}</div>`,'labs');}
function triage(){return shell(`<a class="back" href="#labs">← Back to the practice lab</a><article class="article">${heading('LOCAL EXERCISE · SYNTHETIC DATA','Read the signals.','A student account has a series of sign-in events. You are the first analyst to review them. All addresses below are documentation-only examples.')}<div class="log-block">TIME (UTC)  USER    SOURCE IP       EVENT<br>09:40:11    alex    192.0.2.10      SIGN_IN_SUCCESS<br>09:41:02    alex    198.51.100.24   SIGN_IN_FAILED<br>09:41:07    alex    198.51.100.24   SIGN_IN_FAILED<br>09:41:09    alex    198.51.100.24   SIGN_IN_FAILED<br>09:41:11    alex    198.51.100.24   SIGN_IN_SUCCESS<br>09:42:03    alex    198.51.100.24   MFA_RESET_REQUESTED</div><h2>What can you say with confidence?</h2><p>Repeated failures followed by a success from a different address and a recovery-related action warrant investigation. The log alone does not prove that the account was compromised; a shared network or legitimate recovery could explain parts of the sequence.</p><section class="question"><div class="eyebrow muted">CHOOSE YOUR NEXT STEP</div><h3>Which response is most appropriate?</h3><div class="answers"><button class="answer" data-triage="0">A. Publish the source address and accuse its owner.</button><button class="answer" data-triage="1">B. Preserve events, verify the session and MFA action, and follow the account-compromise playbook.</button><button class="answer" data-triage="2">C. Ignore it because the final login succeeded.</button></div><div class="feedback" role="status"></div></section><h2>Build a short analyst handover</h2><p>Record the timeline, affected account, what you know, what remains uncertain, and the next evidence to request. Consider device details, session history, and the outcome of the MFA reset.</p><textarea class="note-area" data-note="triage" aria-label="Triage field notes" placeholder="Observation → hypothesis → evidence needed → next action">${esc(state.notes.triage||'')}</textarea><a class="btn" href="#project/incident">Turn this into a portfolio project ↗</a></article>`,'labs');}
let pipeline=['Deploy & monitor','Validate data','Train model','Ingest data','Evaluate model','Engineer features'];
const pipelineCorrect=['Ingest data','Validate data','Engineer features','Train model','Evaluate model','Deploy & monitor'];
function pipelineMarkup(){return pipeline.map((s,i)=>`<div class="pipeline-step"><span>0${i+1}</span><strong>${s}</strong><div class="move-btns"><button class="move-btn icon-btn" data-move="${i}" data-direction="-1" aria-label="Move ${s} up" ${i===0?'disabled':''}>↑</button><button class="move-btn icon-btn" data-move="${i}" data-direction="1" aria-label="Move ${s} down" ${i===pipeline.length-1?'disabled':''}>↓</button></div></div>`).join('');}
function pipelineLab(){
 return shell(`<a class="back" href="#labs">← Back to the practice lab</a><article class="article">${heading('THE PIPELINE LAB · PRACTICE WITH PURPOSE','From dataset to deployment.','A hands-on workflow ordering exercise to connect machine learning concepts. Put these stages in the standard order for a dependable production pipeline.')}<div class="banner"><b>Think in pipelines, not just predictions.</b> Validate inputs, prepare features, train and evaluate before release. Monitoring feeds back into earlier stages.</div><div class="pipeline-lab-box"><div class="eyebrow muted">EXERCISE 01 · ORDER THE PIPELINE</div><h3>Arrange the stages in logical sequence</h3><p>Use the up and down arrows to place each stage where it belongs in an end-to-end MLOps workflow.</p><div class="pipeline-steps" id="pipeline-steps">${pipelineMarkup()}</div><div class="pipeline-actions" style="margin-top:1.5rem;display:flex;gap:12px;align-items:center"><button class="btn gold" id="check-pipeline">Check my pipeline →</button><button class="btn outline" id="reset-pipeline">Reset sequence</button></div><div id="lab-feedback" class="feedback" role="status" style="margin-top:1rem;font-size:15px;font-weight:600"></div></div><h2>Guided portfolio projects</h2><div class="career-grid" style="margin-top:1.5rem"><article class="career" data-tone="mint"><span class="module-icon">${icon('layers')}</span><div class="eyebrow muted">GUIDED PROJECT 01</div><h3>Design your own MLOps pipeline</h3><p>Choose house-price prediction, customer churn, or fraud detection. Document objectives, data validation, features, experiment tracking, and CI/CD deployment.</p><a class="text-link" href="#project/mlops-pipeline">Open project brief ↗</a></article><article class="career" data-tone="sky"><span class="module-icon">${icon('terminal')}</span><div class="eyebrow muted">GUIDED PROJECT 02</div><h3>Explore an MLOps platform & tool</h3><p>Study MLflow, Apache Airflow, or Kubeflow. Explain CI/CD support, model validation, deployment strategy, and practical tradeoffs.</p><a class="text-link" href="#project/mlops-tool">Open project brief ↗</a></article></div></article>`,'labs');
}
function project(id){let p=projects.find(x=>x.id===id);if(!p)return missing();let n=Object.values(state.projects[id]||{}).filter(Boolean).length;return shell(`<a class="back" href="#labs">← Back to the practice lab</a><article class="article">${heading(p.type,p.title,p.desc)}<div class="banner"><b>Your project, your evidence.</b> Use synthetic data or an authorized training environment. Keep secrets, personal information, and third-party lab solutions out of public repositories.</div><h2>Your deliverables</h2><p>Use this checklist to track your own work. Ticking an item records your progress; it does not assess the quality of the deliverable.</p><div class="checklist">${p.deliverables.map((x,i)=>`<label><input type="checkbox" data-project="${p.id}" data-item="${i}" ${state.projects[id]?.[i]?'checked':''}><span>${x}</span></label>`).join('')}</div><p class="muted" id="project-count">${n} of 5 deliverables complete</p><h2>README structure</h2><div class="log-block">1. Problem and scope<br>2. Environment and safe setup<br>3. Method and assumptions<br>4. Evidence and findings<br>5. Mitigation and verification<br>6. Limitations and next steps</div><h2>Project notebook</h2><textarea class="note-area" data-note="project-${id}" aria-label="Project notebook" placeholder="Your plan, evidence references, and reflections…">${esc(state.notes['project-'+id]||'')}</textarea><div class="lesson-bottom"><button class="btn outline" data-export="${id}">Download project brief ↓</button>${id==='incident'?'<a class="text-link" href="#labs/triage">Open the synthetic dataset →</a>':id==='appsec'?`<a class="text-link" target="_blank" rel="noopener noreferrer" href="${R.portswigger.url}">Choose a provider-hosted lab ↗</a>`:id==='cloud'?'<a class="text-link" href="#lesson/cloud/0">Review cloud foundations →</a>':'<a class="text-link" href="#lesson/grc/0">Review CSF foundations →</a>'}</div></article>`,'labs');}
function videoCard(v){return `<article class="video-card"><button class="video-cover" data-video="${v.id}" aria-label="Play ${v.title}"><span class="play-circle">▷</span><b>${v.title}</b></button><div class="video-info"><div class="eyebrow">${v.subtitle}</div><p>${v.desc}</p><button class="text-link" style="border:0;background:none;padding:0" data-video="${v.id}">Open video & study notes ↗</button></div></article>`;}
function videoPage(){return watchPage();}
function showVideo(id,start=0){const v=videos.find(x=>x.id===id);if(!v)return;const timestamp=Math.max(0,Number(start)||0);$('#modal-content').innerHTML=`<div class="eyebrow muted">${esc(v.subtitle)}</div><h2 class="modal-heading" style="margin-top:10px">${esc(v.title)}</h2><iframe class="video-frame" src="https://www.youtube-nocookie.com/embed/${v.video}?start=${timestamp}" title="${esc(v.title)}" allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="video-description">${v.desc}</p>${v.caveat?`<p class="video-caveat">${v.caveat}</p>`:''}<div class="lesson-bottom"><a class="text-link" href="https://www.youtube.com/watch?v=${v.video}&t=${timestamp}" target="_blank" rel="noopener noreferrer">Watch on YouTube ↗</a><a class="text-link" href="${v.notesUrl}" target="_blank" rel="noopener noreferrer">${v.notesLabel} ↗</a></div>${v.chapters.length?`<div class="chapter-shortcuts">${v.chapters.map(([name,time])=>`<button class="btn small outline" data-video="${v.id}" data-start="${time}">${name} ▷</button>`).join('')}</div>`:''}<section class="watch-activity"><div class="eyebrow">AFTER YOU WATCH</div><p>${v.activity}</p><a class="text-link" data-close-viewer href="${v.practice}">Open the related exercise →</a></section><label class="note-label" for="video-note">Your idea, question, and example</label><textarea id="video-note" class="note-area" data-note="video-${v.id}" placeholder="One idea I can explain. One question. One example to try.">${esc(state.notes['video-'+v.id]||'')}</textarea><small class="muted">Saved automatically in this browser.</small>`;if(!$('#modal').open)$('#modal').showModal();}
function showStudyBrief(id){const r=resources.find(x=>x.brief===id);if(!r)return;$('#modal-content').innerHTML=`<div class="eyebrow muted">DATA & MLOPS · STUDY BRIEF</div><h2 class="modal-heading">${esc(r.title)}</h2><p class="video-description">${esc(r.desc)}</p>${r.sections.map(s=>`<section class="lesson-section"><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p></section>`).join('')}<div class="lesson-bottom">${r.url?`<a class="text-link" href="${r.url}" target="_blank" rel="noopener noreferrer">Explore original source ↗</a>`:''}<button class="btn small outline" data-close-viewer>Close brief</button></div><label class="note-label" for="brief-note">Your reflection</label><textarea id="brief-note" class="note-area" data-note="brief-${id}" placeholder="Connect this idea to a project or example.">${esc(state.notes['brief-'+id]||'')}</textarea><small class="muted">Saved automatically in this browser.</small>`;if(!$('#modal').open)$('#modal').showModal();}
function progress(){let percent=Math.round(totalDone()/lessonTotal*100),pn=projects.reduce((n,p)=>n+Object.values(state.projects[p.id]||{}).filter(Boolean).length,0);return shell(`${heading('YOUR LEARNING JOURNAL','Small steps add up.','Your progress, saved sources, and project milestones in one place. Everything here belongs to this browser; demo login does not sync it across devices.')}<div class="readiness"><div class="progress-ring" style="--progress:${percent}%"><span>${percent}%</span></div><div><h3>${totalDone()} of ${lessonTotal} lessons complete</h3><p>${moduleCount()} modules completed · ${Object.values(state.answers).filter(v=>v===true).length} checks passed · ${pn} project deliverables marked</p></div></div><a class="btn" href="${nextLesson()}">Continue your learning ↗</a><div class="section-top"><div><h2>Your modules</h2><p>Completion is self-reported. Knowledge checks track correct answers separately.</p></div></div><div class="module-grid">${modules.map(moduleCard).join('')}</div><div class="section-top"><div><h2>Your saved shelf</h2><p>${state.saved.length} resources for another day.</p></div><a class="text-link" href="#library">Browse library ↗</a></div><div class="resource-grid">${resources.filter(r=>state.saved.includes(r.id)).map(resourceCard).join('')||'<div class="empty">Your shelf is ready. Save a resource from the library to find it here.</div>'}</div><div class="section-top"><div><h2>Keep a copy of your learning</h2><p>Download your notes, progress, and project checklist as a readable Markdown journal.</p></div></div><button class="btn outline" id="export-journal">Download learning journal ↓</button><div class="backup-panel" aria-labelledby="backup-heading"><div class="eyebrow">BROWSER BACKUP</div><h3 id="backup-heading">Protect your progress</h3><p>Progress lives only in this browser. Save a backup file you can restore on this device or another browser, or use it before clearing site data.</p><div class="backup-actions"><button class="btn small" id="export-backup">Save a backup ↓</button><label class="btn small outline file-btn" for="import-backup">Restore a backup ↑</label><input id="import-backup" class="screen-reader" type="file" accept="application/json,.json"></div><div id="restore-preview" class="restore-preview" role="status" aria-live="polite"></div><small class="muted">Backups contain your notes and progress only — no password. Avoid storing personal data in notes.</small></div>`,'progress');}
function roadmap(){return curriculumPage();}
function sources(){return shell(`${heading('SOURCES & EDITORIAL NOTES','Curated with care. Credited clearly.','NxGenVarsity Unified Platform is an independent learning companion for engineering students. The short lessons and study sequences are original editorial material; linked providers own their courses, labs, and frameworks.')}<article class="article"><h2>Unified learning experience</h2><p>The platform combines the Cybersecurity curriculum and the Data Engineering & MLOps curriculum in one shared learning shell. Both tracks preserve their original lessons, videos, PDFs, practice exercises, and progress controls.</p><div class="source-links">${videos.filter(v=>v.id!=='accounts').map(v=>`<a href="${v.sourceUrl||v.notesUrl}" target="_blank" rel="noopener noreferrer">${v.provider} · ${v.title} ↗</a>`).join('')}</div><h2>Our starting points</h2><p>The warm colors, dark sidebar, illustrated welcome, and guided-card layout are inspired by the existing studio design system. Cybersecurity topic coverage draws inspiration from <a class="text-link" href="${R.patil.url}" target="_blank" rel="noopener noreferrer">Dr. Basavaraj Patil’s CyberLab ↗</a>. This site is not affiliated with or endorsed by the external organizations linked here.</p><h2>Coverage and learning depth</h2><p>The Cybersecurity curriculum was expanded after reviewing the public Udemy syllabus and all eight CyberLab areas. <a class="text-link" href="#coverage">Inspect the searchable coverage audit →</a>. Lessons, conceptual coverage, safe substitutes, and reference orientations are distinguished. Paid course content was not accessed or reproduced.</p><h2>What “current” means here</h2><p>This is a curated snapshot reviewed on <b>26 November 2026</b>, not a live news feed. The OWASP project identifies its 2025 Top 10 as the current released version. picoCTF’s official page redirects learners to CyLab Security Academy. NIST’s CSF resource center covers CSF 2.0. Follow original pages for later revisions, exam changes, and availability.</p><div class="source-links"><a href="https://owasp.org/www-project-top-ten/" target="_blank" rel="noopener noreferrer">Verify OWASP’s current release ↗</a><a href="https://picoctf.org/" target="_blank" rel="noopener noreferrer">Read the picoCTF transition notice ↗</a></div><h2>Demo account and privacy</h2><p>The login is a demonstration. No real account is created, and passwords are never stored or sent. Progress, notes, bookmarks, and the demo profile are saved in this browser’s local storage. They are not synchronized across devices or shared with other learners. Avoid storing credentials or personal information in notes.</p><p>YouTube embeds load only when you choose a video. The site uses Google Fonts for typography. External resource links open the provider’s own site, where its terms and privacy practices apply.</p><h2>Illustration credit</h2><p>The campus illustrations depict fictional students and were generated for the two original learning studios.</p><h2>Original sources</h2><div class="source-links">${Object.values(R).map(r=>`<a href="${r.url}" target="_blank" rel="noopener noreferrer">${r.title} ↗</a>`).join('')}</div><h2>Use the learning responsibly</h2><p>Practice only within written authorization and the rules of the training environment. Career roadmaps are suggested study paths, not promises of employment. Certification pages are provided for comparison, and legal obligations require current, context-specific review.</p></article>`,'library');}
function login(){
 const loginUrl=['localhost','127.0.0.1','::1'].includes(location.hostname)
  ?'http://localhost:3000/login'
  :new URL('/login',location.origin).href;
 location.replace(loginUrl);
 return `<main id="main" tabindex="-1" class="login-page"><section class="login-form-wrap"><div class="login-card"><div class="eyebrow">NXGENVARSITY SIGN IN</div><h2>Opening secure sign-in…</h2><p>The old demo login has been replaced.</p><a class="btn" href="${esc(loginUrl)}">Continue to sign in ↗</a></div></section></main>`;
}
function missing(){return shell(`${heading('LET’S FIND YOUR WAY','That page isn’t here.','Choose a module from your learning path to continue.')}<a class="btn" href="#home">Go to your learning path →</a>`);}
function showRestorePreview(text,fileName){const check=applyBackup(text,'preview');const box=$('#restore-preview');if(!box)return;
 if(!check.ok){box.innerHTML=`<p class="restore-error">${esc(check.message)}</p>`;pendingBackup=null;return;}
 pendingBackup=text;
 box.innerHTML=`<p><b>${esc(fileName||'Backup file')}</b><br>Contains ${esc(check.summary)}.</p><div class="restore-actions"><button class="btn small" id="restore-merge">Merge with my progress</button><button class="btn small outline" id="restore-replace">Replace everything</button><button class="btn small ghost" id="restore-cancel">Cancel</button></div><p class="muted">Merge keeps what you have and adds new items. Replace makes this browser match the file exactly.</p>`;
}
let pendingBackup=null;
let previousRoute='';
function render(){const hash=location.hash.slice(1)||'home',parts=hash.split('/');$('#modal').close();$('#modal-content').innerHTML='';if(['curriculum','roadmap'].includes(parts[0])&&parts[1])curriculumQuery='';let html;switch(parts[0]){case'home':html=home();break;case'login':html=login();break;case'lesson':html=lesson(parts[1],parts[2]);break;case'library':html=library();break;case'careers':html=careers();break;case'career':html=career(parts[1]);break;case'labs':html=parts[1]==='triage'?triage():parts[1]==='pipeline'?pipelineLab():labs();break;case'project':html=project(parts[1]);break;case'videos':html=videoPage();break;case'progress':html=progress();break;case'roadmap':case'curriculum':html=curriculumPage(parts[1]);break;case'syllabus':html=syllabusPage();break;case'checks':html=checksPage(parts[1],parts[2]);break;case'reference':html=atlasPage(parts[1],parts[2]);break;case'coverage':html=coveragePage();break;case'field':html=fieldPage(parts[1]);break;case'sources':html=sources();break;default:html=missing();}$('#app').innerHTML=html;if(['curriculum','roadmap'].includes(parts[0]))updateCurriculum();if(parts[0]==='videos')updateVideos();if(parts[0]==='library')updateResources();if(parts[0]==='reference'&&!parts[2])updateAtlas();if(parts[0]==='coverage')updateCoverage();if(parts[0]==='field'&&parts[1]==='throttle')updateThrottle();document.title=`${({'home':'My learning path','login':'Demo login','careers':'Career compass','career':'Career roadmap','labs':'Practice lab','project':'Project brief','videos':'Watch & learn','progress':'My progress','library':'Resource library','lesson':modules.find(m=>m.id===parts[1])?.title,'sources':'Sources & credits','curriculum':'Curriculum','syllabus':'Course syllabus','checks':'Knowledge checks','roadmap':'Curriculum','reference':'Knowledge atlas','coverage':'Coverage audit','field':'Field guide'})[parts[0]]||'Explore'} · NxGenVarsity`;if(previousRoute!==hash){window.scrollTo(0,0);if(previousRoute)$('#main')?.focus({preventScroll:true});}previousRoute=hash;if(['curriculum','roadmap'].includes(parts[0])&&parts[1])document.getElementById('phase-'+parts[1])?.scrollIntoView({block:'start'});}
function download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Your download is ready.');}
function exportJournal(){let text='# NxGenVarsity Unified Platform · Learning journal\n\nExported '+new Date().toISOString().slice(0,10)+'\n\n';for(const m of modules){text+='## '+m.title+'\n\n';m.lessons.forEach((l,i)=>{const k=`${m.id}:${i}`;text+=`- [${state.done.includes(k)?'x':' '}] ${l.title}${state.answers[k]?' · Knowledge check passed':''}\n`;if(state.notes[k])text+='\n  Notes: '+state.notes[k]+'\n\n';});text+='\n';}text+='## Saved resources\n\n'+resources.filter(r=>state.saved.includes(r.id)).map(r=>`- [${r.title}](${r.url||R[r.ref]?.url||'#'})`).join('\n')+'\n\n';for(const p of projects){text+='## '+p.title+'\n\n'+p.deliverables.map((v,i)=>`- [${state.projects[p.id]?.[i]?'x':' '}] ${v}`).join('\n')+'\n\n'+(state.notes['project-'+p.id]||'')+'\n\n';}if(state.notes.triage)text+='## Triage field notes\n\n'+state.notes.triage+'\n\n';for(const [key,value] of Object.entries(state.notes)){if(key.startsWith('atlas-')||key.startsWith('video-')||key==='throttle')text+='## '+key+'\n\n'+value+'\n\n';}text+='## Beginner challenges attempted\n\n'+challenges.map((c,i)=>'- ['+(state.challenges?.[i]?'x':' ')+'] '+c.title).join('\n');download('nxgenvarsity-learning-journal.md',text);}
const BACKUP_VERSION=1;
// Only known learner-state keys are restored, so an unexpected file cannot inject fields.
const backupKeys=['done','answers','notes','saved','projects','profile','stage','challenges'];
function backupPayload(){const data={};for(const key of backupKeys)if(state[key]!==undefined&&state[key]!==null)data[key]=state[key];return {app:'nxgenvarsity-unified',version:BACKUP_VERSION,exported:new Date().toISOString(),data};}
function exportBackup(){const stamp=new Date().toISOString().slice(0,10);download(`nxgenvarsity-unified-backup-${stamp}.json`,JSON.stringify(backupPayload(),null,2));}
function backupSummary(s){const done=Array.isArray(s.done)?s.done.length:0;const notes=s.notes&&typeof s.notes==='object'?Object.keys(s.notes).length:0;const saved=Array.isArray(s.saved)?s.saved.length:0;return `${done} lesson${done===1?'':'s'} · ${notes} note${notes===1?'':'s'} · ${saved} saved`;}
// Merge keeps everything already in this browser and adds anything the file has that it lacks.
function mergeInto(data){
 const noteChoice=(a,b)=>(a||'')===''?b:((b||'')===''?a:(b.length>a.length?b:a));
 if(Array.isArray(data.done))data.done.forEach(k=>{if(typeof k==='string'&&!state.done.includes(k))state.done.push(k);});
 if(Array.isArray(data.saved))data.saved.forEach(id=>{if(typeof id==='string'&&!state.saved.includes(id))state.saved.push(id);});
 if(data.notes)for(const [k,v] of Object.entries(data.notes))if(typeof v==='string')state.notes[k]=noteChoice(state.notes[k],v);
 if(data.answers)for(const [k,v] of Object.entries(data.answers)){if(typeof v==='boolean'&&state.answers[k]===undefined)state.answers[k]=v;else if(v===true)state.answers[k]=true;}
 if(data.projects)for(const [id,items] of Object.entries(data.projects)){if(!items||typeof items!=='object')continue;state.projects[id]??={};for(const [item,v] of Object.entries(items))if(v)state.projects[id][item]=true;}
 if(data.profile&&typeof data.profile==='object'&&!state.profile)state.profile=data.profile;
 if(Array.isArray(data.challenges)){state.challenges=Array.isArray(state.challenges)?state.challenges:[];data.challenges.forEach((v,i)=>{if(v)state.challenges[i]=true;});}
}
function applyBackup(text,mode='merge'){
 let parsed;try{parsed=JSON.parse(text);}catch(e){return {ok:false,message:'That file is not valid JSON. Choose an NxGenVarsity backup file.'};}
 const data=parsed&&(parsed.app==='nxgenvarsity-unified'||parsed.app==='cyber-studio')?parsed.data:parsed&&parsed.data?parsed.data:null;
 if(!data||typeof data!=='object'||Array.isArray(data))return {ok:false,message:'That file does not look like an NxGenVarsity backup.'};
 const clean={};for(const key of backupKeys)if(data[key]!==undefined&&data[key]!==null)clean[key]=data[key];
 if(Array.isArray(clean.done))clean.done=clean.done.filter(k=>typeof k==='string');
 else delete clean.done;
 if(Array.isArray(clean.saved))clean.saved=clean.saved.filter(k=>typeof k==='string');
 else delete clean.saved;
 for(const key of ['answers','notes','projects'])if(clean[key]&&(typeof clean[key]!=='object'||Array.isArray(clean[key])))delete clean[key];
 if(!clean.done&&!clean.saved&&!clean.notes&&!clean.answers&&!clean.projects)return {ok:false,message:'No recognizable progress was found in that file.'};
 const summary=backupSummary(clean);
 if(mode==='preview')return {ok:true,summary,mode};
 if(mode==='merge')mergeInto(clean);
 else{for(const key of backupKeys)delete state[key];const fresh={done:[],answers:{},notes:{},saved:[],projects:{},profile:null,challenges:[]};for(const [key,value] of Object.entries(clean))fresh[key]=value;Object.assign(state,fresh);if(![0,1,2].includes(state.stage))state.stage=0;if(state.profile===undefined)state.profile=null;}
 if(!Array.isArray(state.done))state.done=[];
 if(!Array.isArray(state.saved))state.saved=[];
 if(!state.answers||typeof state.answers!=='object'||Array.isArray(state.answers))state.answers={};
 if(!state.notes||typeof state.notes!=='object'||Array.isArray(state.notes))state.notes={};
 if(!state.projects||typeof state.projects!=='object'||Array.isArray(state.projects))state.projects={};
 persist();
 return {ok:true,summary,mode};
}
document.addEventListener('click',e=>{
 if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView();return;}
 if(e.target.closest('[data-close-viewer]'))$('#modal').close();
 const moveBtn=e.target.closest('[data-move]');if(moveBtn){const i=Number(moveBtn.dataset.move),j=i+Number(moveBtn.dataset.direction);if(j>=0&&j<pipeline.length){[pipeline[i],pipeline[j]]=[pipeline[j],pipeline[i]];const el=$('#pipeline-steps');if(el)el.innerHTML=pipelineMarkup();const fb=$('#lab-feedback');if(fb)fb.textContent='';}return;}
 if(e.target.closest('#check-pipeline')){const ok=pipeline.every((s,i)=>s===pipelineCorrect[i]);const fb=$('#lab-feedback');if(fb){fb.style.color=ok?'var(--mint)':'var(--peach)';fb.textContent=ok?'✓ Well connected! Validate inputs, prepare features, train, and evaluate before release. Monitoring feeds back into earlier stages.':'Start with ingestion and data validation. Features must be ready before training, and evaluation must come before release.';if(ok){state.pipelineLab=true;persist();}}return;}
 if(e.target.closest('#reset-pipeline')){pipeline=['Deploy & monitor','Validate data','Train model','Ingest data','Evaluate model','Engineer features'];const el=$('#pipeline-steps');if(el)el.innerHTML=pipelineMarkup();const fb=$('#lab-feedback');if(fb)fb.textContent='';return;}
 const expand=e.target.closest('[data-flow-expand]');if(expand){document.querySelectorAll('.curriculum-phase').forEach(d=>d.open=expand.dataset.flowExpand==='true');return;}
 if(e.target.closest('#download-syllabus')){download('nxgenvarsity-cybersecurity-syllabus.md',syllabusMarkdown());return;}
 const stage=e.target.closest('[data-stage]');if(stage){state.stage=Number(stage.dataset.stage);persist();const y=window.scrollY;render();window.scrollTo(0,y);return;}
 const menu=e.target.closest('.mobile-toggle');if(menu){const open=$('.sidebar').classList.toggle('open');menu.setAttribute('aria-expanded',open);return;}
 if(e.target.closest('.nav-close')){$('.sidebar').classList.remove('open');$('.mobile-toggle').setAttribute('aria-expanded','false');$('.mobile-toggle').focus();return;}
 const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;const has=state.saved.includes(id);state.saved=has?state.saved.filter(x=>x!==id):[...state.saved,id];persist();save.textContent=has?'+ Save':'✓ Saved';save.classList.toggle('saved',!has);save.setAttribute('aria-pressed',!has);if($('#resource-grid'))updateResources();toast(has?'Removed from your saved shelf.':'Saved to your learning shelf.');return;}
 const brief=e.target.closest('[data-study-brief]');if(brief){showStudyBrief(brief.dataset.studyBrief);return;}
 const bankAns=e.target.closest('[data-bank-answer]');
 if(bankAns){const moduleId=bankAns.dataset.bankModule,index=Number(bankAns.dataset.bankIndex),q=modules.find(m=>m.id===moduleId)?.quizBank?.[index];if(!q)return;const correct=Number(bankAns.dataset.bankAnswer)===q.correct,parent=bankAns.closest('.question');parent.querySelectorAll('.answer').forEach(b=>b.classList.remove('correct','incorrect'));bankAns.classList.add(correct?'correct':'incorrect');parent.querySelector('.feedback').textContent=(correct?'✓ ':'Try again. ')+q.explanation;const key=`quiz:${moduleId}:${index}`;if(state.answers[key]!==true||!correct){state.answers[key]=correct;persist();}return;}
 const ans=e.target.closest('[data-answer]');if(ans){const m=modules.find(x=>x.id===ans.dataset.module),i=Number(ans.dataset.lesson),l=m.lessons[i],key=`${m.id}:${i}`,correct=Number(ans.dataset.answer)===l.correct;const parent=ans.closest('.question,.article,section');if(!parent)return;parent.querySelectorAll('.answer').forEach(b=>b.classList.remove('correct','incorrect'));ans.classList.add(correct?'correct':'incorrect');const fb=parent.querySelector('.feedback');if(fb)fb.textContent=correct?'✓ '+l.explanation:'Try again. '+l.explanation;
  if(correct){if(state.answers[key]!==true){state.answers[key]=true;persist();}}
  else if(state.answers[key]!==true&&state.answers[key]!==false){state.answers[key]=false;persist();}
  const review=ans.closest('[data-review]');
  if(review){if(correct){toast('Cleared. One fewer to revisit.');setTimeout(()=>render(),450);}else{const again=review.querySelector('[data-review-next]');if(again)again.hidden=false;}}
  return;}
 const complete=e.target.closest('[data-complete]');if(complete){const key=complete.dataset.complete;if(!state.done.includes(key)){state.done.push(key);persist();complete.innerHTML='✓ Lesson completed';complete.classList.add('outline');toast('One more step forward. Lesson completed.');}else toast('You’ve already completed this lesson.');return;}
 const vid=e.target.closest('[data-video]');if(vid){showVideo(vid.dataset.video,vid.dataset.start);return;}
 const tri=e.target.closest('[data-triage]');if(tri){const correct=tri.dataset.triage==='1';tri.closest('.answers').querySelectorAll('button').forEach(b=>b.classList.remove('correct','incorrect'));tri.classList.add(correct?'correct':'incorrect');tri.closest('.question').querySelector('.feedback').textContent=correct?'✓ Good judgment. Preserve the evidence, validate the session and recovery action, and escalate according to a defined playbook. The log alone cannot confirm a compromise.':'Keep investigating. An address is not a person’s identity, and a successful login can still be suspicious. Preserve evidence and verify context.';return;}
 if(e.target.closest('#saved-only')){onlySaved=!onlySaved;const b=$('#saved-only');b.textContent=onlySaved?'✓ Saved only':'Show saved';b.setAttribute('aria-pressed',onlySaved);updateResources();return;}
 const exp=e.target.closest('[data-export]');if(exp){const p=projects.find(x=>x.id===exp.dataset.export);download(`nxgenvarsity-${p.id}-brief.md`,`# ${p.title}\n\n${p.desc}\n\n## Deliverables\n\n${p.deliverables.map((v,i)=>`- [${state.projects[p.id]?.[i]?'x':' '}] ${v}`).join('\n')}\n\n## Notes\n\n${state.notes['project-'+p.id]||''}\n\nUse synthetic data or authorized training environments only.`);return;}
 if(e.target.closest('#export-journal'))exportJournal();
 if(e.target.closest('#export-backup')){exportBackup();return;}
 if(e.target.closest('#restore-cancel')){pendingBackup=null;const box=$('#restore-preview');if(box)box.innerHTML='';const input=$('#import-backup');if(input)input.value='';return;}
 const restore=e.target.closest('#restore-merge,#restore-replace');if(restore){if(!pendingBackup)return;const mode=restore.id==='restore-replace'?'replace':'merge';const result=applyBackup(pendingBackup,mode);pendingBackup=null;const input=$('#import-backup');if(input)input.value='';if(!result.ok){toast(result.message);return;}toast(mode==='replace'?`Progress replaced with ${result.summary}.`:`Backup merged: ${result.summary}.`);render();return;}
 const nextQ=e.target.closest('[data-review-next]');if(nextQ){location.hash=nextQ.dataset.reviewNext;return;}
});
document.addEventListener('input',e=>{if(e.target.id==='curriculum-search'){curriculumQuery=e.target.value;updateCurriculum();}if(e.target.id==='video-search'){videoQuery=e.target.value;updateVideos();}if(e.target.id==='resource-search'){resourceQuery=e.target.value;updateResources();}if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;persist();}});
document.addEventListener('change',e=>{
 if(e.target.id==='import-backup'){const file=e.target.files&&e.target.files[0];if(!file)return;const reader=new FileReader();reader.onload=()=>showRestorePreview(String(reader.result||''),file.name);reader.onerror=()=>toast('That file could not be read. Try again.');reader.readAsText(file);return;}
 if(e.target.id==='check-module')location.hash='checks/'+e.target.value;if(e.target.id==='video-topic'){videoTopic=e.target.value;updateVideos();}if(e.target.id==='resource-filter'){resourceFilter=e.target.value;updateResources();}if(e.target.dataset.project){const id=e.target.dataset.project;state.projects[id]??={};state.projects[id][e.target.dataset.item]=e.target.checked;persist();$('#project-count').textContent=`${Object.values(state.projects[id]).filter(Boolean).length} of 5 deliverables complete`;}});
$('.modal-close').addEventListener('click',()=>$('#modal').close());$('#modal').addEventListener('close',()=>$('#modal-content').innerHTML='');$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.sidebar')?.classList.contains('open')){$('.sidebar').classList.remove('open');$('.mobile-toggle').setAttribute('aria-expanded','false');$('.mobile-toggle').focus();}});
document.addEventListener('pointermove',e=>{
 const target=e.target instanceof Element?e.target:null;
 const main=target?.closest('.main-wrap');
 if(main){
  if(e.pointerType==='mouse'&&!matchMedia('(prefers-reduced-motion: reduce)').matches){
   let clip=main.querySelector('.cursor-glow-clip');
   if(!clip){clip=document.createElement('div');clip.className='cursor-glow-clip';clip.setAttribute('aria-hidden','true');clip.innerHTML='<div class="cursor-glow"></div>';main.prepend(clip);}
   const glow=clip.querySelector('.cursor-glow'),rect=main.getBoundingClientRect();
   glow.style.setProperty('--cursor-glow-x',`${(e.clientX-rect.left).toFixed(1)}px`);
   glow.style.setProperty('--cursor-glow-y',`${(e.clientY-rect.top).toFixed(1)}px`);
   glow.style.opacity='1';
  }else main.querySelector('.cursor-glow')?.style.setProperty('opacity','0');
 }
 const glass=target?.closest('.course-dashboard-card,.module,.resource-card,.career,.next-step,.mission,.field-note,.profile');
 if(!glass)return;
 const rect=glass.getBoundingClientRect();
 if(!rect)return;
 const x=((e.clientX-rect.left)/rect.width)*100;
 glass.style.setProperty('--glass-x',`${Math.max(0,Math.min(100,x))}%`);
});
document.addEventListener('pointerout',e=>{
 const target=e.target instanceof Element?e.target:null,main=target?.closest('.main-wrap');
 if(!main||(e.relatedTarget instanceof Node&&main.contains(e.relatedTarget)))return;
 main.querySelector('.cursor-glow')?.style.setProperty('opacity','0');
});
window.addEventListener('hashchange',render);render();
